import { Btn } from "@/registry/p1/internal/btn";
import { Icon } from "@/registry/p1/internal/icons";
import "./pricing.css";

export interface PricingTier {
  name: string;
  price: string;
  period: string;
  features: string;
  buttonLabel: string;
  featured: "off" | "on";
}
export interface PricingProps {
  eyebrow: string;
  heading: string;
  subtitle: string;
  tiers: PricingTier[];
}

const splitLines = (s: string) =>
  String(s || "")
    .split("\n")
    .map((x) => x.trim())
    .filter(Boolean);

export function PricingRender({ eyebrow, heading, subtitle, tiers }: PricingProps) {
  const list = tiers || [];
  const cols = Math.min(4, Math.max(1, list.length));
  return (
    <div className="p1-pricing p1-block">
      <div className="p1-pricing__inner">
        <div className="p1-pricing__header">
          {eyebrow && <p className="p1-pricing__eyebrow">{eyebrow}</p>}
          {heading && <h2 className="p1-pricing__heading">{heading}</h2>}
          {subtitle && <p className="p1-pricing__subtitle">{subtitle}</p>}
        </div>
        <div
          className="p1-pricing__grid"
          style={{ gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))` }}
        >
          {list.map((tier, i) => {
            const hot = tier.featured === "on";
            return (
              <div key={i} className="p1-pricing__card" data-featured={tier.featured}>
                {hot && (
                  <span className="p1-pricing__badge">Most popular</span>
                )}
                <div className="p1-pricing__tier-name">{tier.name}</div>
                <div className="p1-pricing__price-row">
                  <span className="p1-pricing__price">{tier.price}</span>
                  {tier.period && <span className="p1-pricing__period">{tier.period}</span>}
                </div>
                <ul className="p1-pricing__features">
                  {splitLines(tier.features).map((f, j) => (
                    <li key={j} className="p1-pricing__feature">
                      <Icon name="check" strokeWidth={3} className="p1-pricing__check" />
                      <span className="p1-pricing__feature-text">{f}</span>
                    </li>
                  ))}
                </ul>
                <Btn variant={hot ? "yellow" : "secondary"} className="p1-pricing__btn">
                  {tier.buttonLabel}
                </Btn>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { PricingRender, type PricingProps, type PricingTier } from "./pricing";
export type { PricingProps, PricingTier };

export const PricingBlock: ComponentConfig<PricingProps> = {
  fields: {
    eyebrow: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Short label above the heading. 1–3 words. E.g. Pricing." },
    },
    heading: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Section heading. Value-focused, under 10 words." },
    },
    subtitle: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "1–2 sentence reassurance below the heading. E.g. start free." },
    },
    tiers: {
      type: "array" as const,
      arrayFields: {
        name: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "Plan name. 1–2 words. E.g. Starter, Team, Enterprise." },
        },
        price: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "Displayed price. E.g. $49 or Custom." },
        },
        period: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "Billing period. E.g. /mo or leave blank." },
        },
        features: {
          type: "textarea" as const,
          ai: { instructions: "One feature per line. Plain text. 3–6 lines." },
        },
        buttonLabel: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "CTA label. 2–4 words. E.g. Start free trial." },
        },
        featured: {
          type: "radio" as const,
          options: [
            { label: "Off", value: "off" },
            { label: "On", value: "on" },
          ],
        },
      },
      defaultItemProps: { name: "Plan", price: "$0", period: "/mo", features: "Feature one\nFeature two", buttonLabel: "Choose plan", featured: "off" },
      getItemSummary: (item: PricingTier) => item.name || "Tier",
    },
  },
  defaultProps: {
    eyebrow: "Pricing",
    heading: "Plans that scale with your portfolio.",
    subtitle: "Start free. Upgrade when your team is ready.",
    tiers: [
      { name: "Starter", price: "$0", period: "/mo", features: "1 project\nCore features\nCommunity support", buttonLabel: "Start free", featured: "off" },
      { name: "Team", price: "$49", period: "/mo", features: "Up to 10 projects\nAdvanced features\nRole-based access\nPriority support", buttonLabel: "Start free trial", featured: "on" },
      { name: "Enterprise", price: "Custom", period: "", features: "Unlimited sites\nBulk updates\nSSO & audit logs\nDedicated CSM", buttonLabel: "Contact sales", featured: "off" },
    ],
  },
  render: PricingRender,
};

export const meta = defineMeta({
  title: 'Pricing',
  description: 'Pricing tier cards with name, price, period, feature list, and CTA button, supporting a featured/highlighted tier; use for pricing pages.',
  categories: ["convert"],
  published: true,
  registryDependencies: ["@p1/tokens","@p1/internal-btn","@p1/internal-icons"],
});

.p1-pricing { background-color: var(--p1-surface-subtle); }

.p1-pricing__inner {
  margin-inline: auto;
  max-inline-size: var(--p1-container-wide);
}

.p1-pricing__header {
  margin-block-end: var(--p1-space-xl);
  text-align: center;
}
.p1-pricing__eyebrow {
  color: var(--p1-accent);
  font-size: var(--p1-text-xl);
  font-style: italic;
  margin-block-end: var(--p1-space-sm);
}
.p1-pricing__heading {
  font-size: var(--p1-text-2xl);
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.02em;
  text-wrap: balance;
}
@media (width >= 48rem) {
  .p1-pricing__heading { font-size: var(--p1-text-3xl); }
}
.p1-pricing__subtitle {
  color: var(--p1-fg-muted);
  margin-block-start: var(--p1-space-sm);
}

.p1-pricing__grid {
  align-items: start;
  display: grid;
  gap: var(--p1-space-md);
  grid-template-columns: 1fr;
}
@media (width < 48rem) {
  .p1-pricing__grid { grid-template-columns: 1fr !important; }
}

.p1-pricing__card {
  border-radius: var(--p1-radius-card);
  border: 1px solid var(--p1-border);
  background-color: var(--p1-surface-default);
  box-shadow: var(--p1-shadow-sm);
  color: var(--p1-fg-default);
  padding: var(--p1-space-lg);
  position: relative;
}
.p1-pricing__card[data-featured="on"] {
  background-color: var(--p1-accent);
  border-color: var(--p1-accent);
  box-shadow: var(--p1-shadow-card-featured);
  color: var(--p1-fg-inverse);
  transform: translateY(-0.5rem);
}

.p1-pricing__badge {
  background-color: var(--p1-warning);
  border-radius: var(--p1-radius-pill);
  color: var(--p1-fg-default);
  font-size: 0.625rem;
  font-weight: var(--p1-weight-bold);
  inset-block-start: -0.75rem;
  inset-inline-start: 50%;
  letter-spacing: 0.08em;
  padding: 0.2rem var(--p1-space-sm);
  position: absolute;
  text-transform: uppercase;
  transform: translateX(-50%);
}

.p1-pricing__tier-name { font-weight: var(--p1-weight-bold); }

.p1-pricing__price-row {
  align-items: baseline;
  display: flex;
  gap: 0.25rem;
  margin-block: var(--p1-space-sm) var(--p1-space-md);
}
.p1-pricing__price {
  font-size: var(--p1-text-3xl);
  font-weight: 800;
  letter-spacing: -0.02em;
}
.p1-pricing__period {
  font-size: var(--p1-text-sm);
  opacity: 0.7;
}

.p1-pricing__features {
  display: flex;
  flex-direction: column;
  gap: var(--p1-space-sm);
  list-style: none;
  margin-block-end: var(--p1-space-lg);
  padding: 0;
}
.p1-pricing__feature {
  align-items: start;
  display: flex;
  font-size: var(--p1-text-sm);
  gap: var(--p1-space-sm);
}
.p1-pricing__check {
  block-size: 1rem;
  color: var(--p1-success);
  flex: none;
  inline-size: 1rem;
  margin-block-start: 0.125rem;
}
.p1-pricing__card[data-featured="on"] .p1-pricing__check { color: var(--p1-warning); }

.p1-pricing__feature-text { color: var(--p1-fg-muted); }
.p1-pricing__card[data-featured="on"] .p1-pricing__feature-text { color: var(--p1-fg-inverse-faint); }

.p1-pricing__btn { inline-size: 100%; justify-content: center; }

